INSERT INTO academy_way_missions (slug, path, position, title, outcome, build, flip, integrate, verify, link) VALUES
  ('survival-field-drills', 'survival-mastery-domains', 600, '27 Field Drills', 'Work through a decision in each of the six domains and complete the shared capstone.', 'Choose Protection, Money, Kinship, Homestead, Meta-Learning or Civic Literacy. In the chosen path, open the Field drill that matches your lesson.', 'Identify the facts, the decision, and one thing that would change your answer.', 'Complete the transfer exercise in your chosen drill and replay it with the original evidence or a source check.', 'Keep the decision, reason, source and proof sheet. A second learner should be able to reproduce the key step.', 'way/mastery-civic/survival-field-drill-27/'),
  ('survival-field-drill-01', 'mastery-protection', 601, 'Field drill · Situational Threat & Predatory Pattern Recognition', 'Complete a scenario decision and demonstrate it on a changed example.', 'A volunteer asks a teen to switch to a private chat and keep the conversation secret. The teen tells you and says nothing happened in person. Choices: 1. Support the teen, stop the private contact, and follow safeguarding and reporting procedures using what was observed. / 2. Tell the teen the messages are probably harmless. / 3. Question the volunteer in front of the teen.', 'Use the principle “Protecting The One” to choose who needs support before documenting anything.', 'Write a three-line report that preserves the original statement, separates facts from guesses, and identifies who can help.', 'Worked response: Support the teen, stop the private contact, and follow safeguarding and reporting procedures using what was observed. The secrecy request is an observable cue. Reassure the teen, protect their privacy, and use an appropriate safeguarding channel. Do not confront or investigate on your own. Source to consult: NCMEC · Online enticement and grooming prevention.', 'institution/foundation/architecture/course/'),
  ('survival-field-drill-02', 'mastery-protection', 602, 'Field drill · De-escalation, Verbal Judo & Command Presence', 'Complete a scenario decision and demonstrate it on a changed example.', 'In a queue, someone raises their voice over a missed appointment. You have room to step back, and no threat has been made. Choices: 1. Step between the person and the exit. / 2. Acknowledge the missed appointment, keep personal space, and offer a clear next step. / 3. Match their volume so the instruction is heard.', 'Mark the observation, inference, and question that matters to the next action.', 'Role-play the sentence. Then have a partner add a credible threat and describe how you would disengage.', 'Worked response: Acknowledge the missed appointment, keep personal space, and offer a clear next step. A calm response can be appropriate while the situation is safe. If a credible threat develops, disengage and get help. Source to consult: CISA · De-escalation Action Guide.', 'way/language/gaslighting-and-plain-truth/'),
  ('survival-field-drill-03', 'mastery-protection', 603, 'Field drill · Emergency Triage, Trauma & Field Medicine', 'Complete a scenario decision and demonstrate it on a changed example.', 'A fictional workshop has been made safe. An adult has life-threatening external bleeding. Another person is with you. Choices: 1. Take the injured person to another room before contacting help. / 2. Wait to finish documenting the injury before involving emergency services. / 3. Assign the other person to call emergency services while you use direct pressure and follow dispatcher instructions.', 'Mark the observation, inference, and question that matters to the next action.', 'Rehearse a ten-second dispatch handoff and demonstrate direct pressure on a training pad. Describe a separate handoff for suspected fracture, burn, and shock.', 'Worked response: Assign the other person to call emergency services while you use direct pressure and follow dispatcher instructions. A safe scene, prompt emergency activation, and direct pressure are the priorities in this training scenario. Keep first-aid care within your training and follow dispatch guidance. Source to consult: American Heart Association and American Red Cross · First Aid Guidelines.', 'institution/foundation/architecture/course/'),
  ('survival-field-drill-04', 'mastery-money', 604, 'Field drill · Barter, Direct Exchange & Value Creation', 'Complete a scenario decision and demonstrate it on a changed example.', 'Three apples are on a table. You agree to give two today for a bicycle patch done Friday. One apple stays with you. Choices: 1. Record three transferred because the trade is worth three to you. / 2. Record the service as received today. / 3. Record two transferred, one retained, the Friday service owed, and the agreed value and dates.', 'Use Nathan Tabor’s Three Apples ledger to track the two units that moved and the one that stayed.', 'Make a Three Apples ledger and add the Friday completion receipt. Point to every unit and distinguish what has moved from what is still owed.', 'Worked response: Record two transferred, one retained, the Friday service owed, and the agreed value and dates. The count is two plus one equals three. The service is promised until completed, and its value and applicable reporting rules are separate questions. Source to consult: IRS · Bartering income.', 'institution/foundation/three-apples/'),
  ('survival-field-drill-05', 'mastery-money', 605, 'Field drill · Contract Forensics & Loophole Spotting', 'Complete a scenario decision and demonstrate it on a changed example.', 'An advertisement says Cancel anytime. The attached sample contract says written notice must arrive ten days before renewal to avoid another charge. Choices: 1. Assume every renewal clause is enforceable in every jurisdiction. / 2. Highlight the notice clause, calendar the deadline, and ask for any promised flexibility in writing. / 3. Use the advertisement alone as the renewal calendar.', 'Mark the observation, inference, and question that matters to the next action.', 'Mark the clause, notice method and renewal date. Draft one specific question to clarify the apparent conflict.', 'Worked response: Highlight the notice clause, calendar the deadline, and ask for any promised flexibility in writing. The two statements should be reconciled before relying on them. Capture the wording, the deadline and the missing guarantee. Applicable law and enforceability require their own review. Source to consult: CFPB · Your Money, Your Goals.', 'institution/foundation/reality-math/'),
  ('survival-field-drill-06', 'mastery-money', 606, 'Field drill · Tax, Debt & Currency Mechanics', 'Complete a scenario decision and demonstrate it on a changed example.', 'On a fictional 1,000 principal, offer A is 90 each month for 12 months and offer B is 60 each month for 20 months. Neither example includes separate fees. Choices: 1. B costs less because the monthly payment is smaller. / 2. A totals 1,080 and B totals 1,200. Check APR and any fees separately. / 3. Both cost the same because the principal is the same.', 'Mark the observation, inference, and question that matters to the next action.', 'Make a ledger showing principal, total paid, and unpaid questions. Then show what a fixed 100 buys before and after a 10 percent price increase.', 'Worked response: A totals 1,080 and B totals 1,200. Check APR and any fees separately. Multiply each payment by its number of payments. The payment total in B is 120 higher. An APR comparison and fees need the full disclosures. Source to consult: CFPB · Your Money, Your Goals.', 'institution/foundation/reality-math/'),
  ('survival-field-drill-07', 'mastery-kinship', 607, 'Field drill · Attachment, Trauma & Generational Cycles', 'Complete a scenario decision and demonstrate it on a changed example.', 'In a fictional family meeting, someone goes quiet when their mistake is mentioned publicly. You need to discuss what happened. Choices: 1. Require the person to explain their childhood to the whole group. / 2. Assign an attachment diagnosis on the spot. / 3. Describe the observable action and offer a private conversation or time to respond.', 'Mark the observation, inference, and question that matters to the next action.', 'Draw a trigger, response and effect map. Write a script that gives a choice and names the issue clearly.', 'Worked response: Describe the observable action and offer a private conversation or time to respond. An observation is distinct from a diagnosis. A private choice can support safety, voice and accountability without requiring disclosure. Source to consult: SAMHSA · Trauma-informed approaches.', 'way/language/read-back-the-exact-words/'),
  ('survival-field-drill-08', 'mastery-kinship', 608, 'Field drill · Boundary Enforcement & "Yes Means Yes / No Means No"', 'Complete a scenario decision and demonstrate it on a changed example.', 'A friend said yes to sharing a file yesterday and says no before you send it today. Choices: 1. Send it unless they give a reason for changing their mind. / 2. Send it because permission existed yesterday. / 3. Treat the no as current. Leave the file unsent and confirm the decision plainly.', 'Use the exact language of the answer. Keep the wording of the former and current decisions.', 'Write a one-sentence readback. Try again with an ambiguous response and state which action you will pause until permission is clear.', 'Worked response: Treat the no as current. Leave the file unsent and confirm the decision plainly. The current answer governs this proposed sharing. A person can withdraw permission. Silence, delay or pressure does not replace a clear answer. Source to consult: RAINN · Consent and prevention.', 'way/language/read-back-the-exact-words/'),
  ('survival-field-drill-09', 'mastery-kinship', 609, 'Field drill · Choosing Partners, Allies & Friends', 'Complete a scenario decision and demonstrate it on a changed example.', 'A potential collaborator misses one deadline, tells you early, and delivers when they promised to catch up. You have three other dated records of follow-through. Choices: 1. Record the missed deadline, notice and repair. Use the dated pattern to set a proportionate next commitment. / 2. Ignore the missed deadline and the communication. / 3. Give them unrestricted access because their explanation sounded sincere.', 'Mark the observation, inference, and question that matters to the next action.', 'Build a five-row reliability timeline and identify what future observation would change your decision.', 'Worked response: Record the missed deadline, notice and repair. Use the dated pattern to set a proportionate next commitment. Read behavior over time, including how a person acknowledges and repairs a lapse. Keep access and responsibility proportional to the observed pattern. Source to consult: SAMHSA · Trauma-informed approaches.', 'way/language/gaslighting-and-plain-truth/'),
  ('survival-field-drill-10', 'mastery-homestead', 610, 'Field drill · Water Sourcing, Filtration & Storage', 'Complete a scenario decision and demonstrate it on a changed example.', 'After a flood, the advisory says fuel may have entered the tap-water system. You have a verified bottled supply. Choices: 1. Boil the tap water and use it. / 2. Use the water if it looks clear after filtering through cloth. / 3. Use the verified alternate supply and follow the local health advisory.', 'Mark the observation, inference, and question that matters to the next action.', 'Create two response cards, one for a boil-water advisory and one for suspected chemical contamination. Record what would trigger switching sources.', 'Worked response: Use the verified alternate supply and follow the local health advisory. Boiling targets germs. It does not remove fuel or make chemically contaminated water safe. A verified alternate supply and the local advisory govern this case. Source to consult: CDC · Water safety in an emergency.', 'way/human-arc-future/human-arc-method-30/'),
  ('survival-field-drill-11', 'mastery-homestead', 611, 'Field drill · Food Preservation & Long-Term Storage', 'Complete a scenario decision and demonstrate it on a changed example.', 'You plan to preserve plain green beans for shelf storage. A neighbor suggests using the timing for jam. Choices: 1. Use the jam timing because both foods are packed in jars. / 2. Use the smell after processing to decide if it was safe. / 3. Find the current tested pressure-canning process for plain green beans and check the equipment and elevation.', 'Mark the observation, inference, and question that matters to the next action.', 'Compare a tested high-acid recipe and a tested low-acid recipe. Record each source, food condition, equipment, and elevation adjustment without processing food in the drill.', 'Worked response: Find the current tested pressure-canning process for plain green beans and check the equipment and elevation. Plain green beans are a low-acid food. Safe shelf canning requires the corresponding research-tested pressure process. Smell is an unreliable success check. Source to consult: National Center for Home Food Preservation · Safe canning.', 'way/human-learning-arc/'),
  ('survival-field-drill-12', 'mastery-homestead', 612, 'Field drill · Plumbing, Framing, Roofing & Basic Repair', 'Complete a scenario decision and demonstrate it on a changed example.', 'A ceiling stain grows after rain near an electrical fixture. You are viewing it from a dry area. Choices: 1. Keep people clear, record the observation from safety, and contact qualified help. / 2. Climb onto the wet roof to find the path. / 3. Open the fixture to see whether water reached it.', 'Mark the observation, inference, and question that matters to the next action.', 'Draw the suspected water path on a classroom diagram and name what evidence a qualified worker would need to inspect.', 'Worked response: Keep people clear, record the observation from safety, and contact qualified help. Water near wiring makes the area unsafe to investigate yourself. The useful handoff is a date, location, change, and description from a safe position. Source to consult: U.S. Fire Administration · Home fire prevention.', 'way/human-learning-arc/'),
  ('survival-field-drill-13', 'mastery-learning', 613, 'Field drill · Neuro-Diversity & Processing Styles', 'Complete a scenario decision and demonstrate it on a changed example.', 'A learner completes an assembly with a diagram and a model but struggles with a spoken-only version. Choices: 1. Repeat the same spoken instructions louder. / 2. Use equivalent representations and check performance on a comparable new task. / 3. Label the learner permanently as a visual learner.', 'Use QI (Quick Intellingence) to fit the representation to the task and QE (Quintessential Empathy) to ask what access support helps.', 'Run forward steps and a reverse dependency diagram against the same objective. Record task accuracy and which support the learner chose.', 'Worked response: Use equivalent representations and check performance on a comparable new task. Representations can improve access for a task. Compare performance while holding the objective steady and leave fixed labels out of the result. Source to consult: CAST · Universal Design for Learning.', 'way/human-learning-arc/'),
  ('survival-field-drill-14', 'mastery-learning', 614, 'Field drill · Memory Compression & Recall Systems', 'Complete a scenario decision and demonstrate it on a changed example.', 'A learner reads a list five times but can only recall four of its eight steps later. Choices: 1. Assign a sixth uninterrupted reread and score how easy it feels. / 2. Ask for recall with the list covered, check missing steps, and schedule a delayed retest. / 3. Compress the list to a slogan and assume skipped details will return.', 'Mark the observation, inference, and question that matters to the next action.', 'Build a cue and test recall now and after a delay. Keep omissions visible and reuse the skill in a different example.', 'Worked response: Ask for recall with the list covered, check missing steps, and schedule a delayed retest. Retrieval and spacing reveal what can be used later. Compression helps only if the compressed cue can recover the relevant details. Source to consult: Institute of Education Sciences · Study and practice.', 'way/human-learning-arc/'),
  ('survival-field-drill-15', 'mastery-learning', 615, 'Field drill · Unlearning & Resetting ("1 - 1 = 0")', 'Complete a scenario decision and demonstrate it on a changed example.', 'A class has been using the rule that a lower monthly payment means a cheaper loan. A worked example contradicts it. Choices: 1. Keep both records, clear the faulty rule, and retest a replacement based on total cost and terms. / 2. Keep the rule because it often feels true. / 3. Delete the earlier worksheet and leave no trace.', '1−1=0 · CLEAR. Remove the unsupported premise from the decision while preserving a dated record of the correction.', 'Produce a before-and-after rule card. Give a second counterexample and state what would force another revision.', 'Worked response: Keep both records, clear the faulty rule, and retest a replacement based on total cost and terms. 1−1=0 clears the unsupported rule from decision-making. Keeping a dated correction lets a second learner reconstruct why it changed. Source to consult: Institute of Education Sciences · Study and practice.', 'way/life/correct-the-record-without-erasing-it/'),
  ('survival-field-drill-16', 'mastery-civic', 616, 'Field drill · Public Records, FOIA & Legal Self-Representation', 'Complete a scenario decision and demonstrate it on a changed example.', 'You want a federal agency memo, a North Carolina county agenda, and a state court docket. Choices: 1. Send the three items as one federal FOIA request to a court clerk. / 2. Identify each custodian and use the applicable federal, county, or court access route. / 3. Ask the county to create a memo answering all your questions.', 'Mark the observation, inference, and question that matters to the next action.', 'Draft a narrow dated request for the memo and a separate contact plan for each local or court record.', 'Worked response: Identify each custodian and use the applicable federal, county, or court access route. Federal FOIA concerns federal agency records. The county and state court examples follow their own processes. Start with posted records and request a specific existing item if needed. Source to consult: FOIA.gov · Federal records requests.', 'institution/civics/'),
  ('survival-field-drill-17', 'mastery-civic', 617, 'Field drill · Local Governance & Zoning Mechanics', 'Complete a scenario decision and demonstrate it on a changed example.', 'A parcel listing says agriculture exempt. The planned use includes occasional paid public events. Choices: 1. Identify the parcel''s jurisdiction and current ordinance and ask the applicable planning office about the proposed use. / 2. Apply the neighboring county''s zoning map. / 3. Assume the phrase on the listing covers the event use.', 'Mark the observation, inference, and question that matters to the next action.', 'Make a parcel fact sheet and cite the defined use, applicable authority, and a dated written question.', 'Worked response: Identify the parcel''s jurisdiction and current ordinance and ask the applicable planning office about the proposed use. A property label does not establish authority or the scope of an exemption. North Carolina Chapter 160D is a state framework. Verify the local rule for the exact parcel and activity. Source to consult: North Carolina General Assembly · Chapter 160D.', 'way/humanities/one-decision/'),
  ('survival-field-drill-18', 'mastery-protection', 618, 'Field drill · Household Emergency Planning & Accessible Evacuation', 'Complete a scenario decision and demonstrate it on a changed example.', 'A practice evacuation closes the only planned route. One person needs step-free access, and a cell phone has no service. Choices: 1. Ask everyone to find another route on their own. / 2. Call the inaccessible route good enough because the drill is fictional. / 3. Rehearse a step-free alternate route, a prearranged check-in method and a shared meeting place.', 'Mark the observation, inference, and question that matters to the next action.', 'Draw two routes on a floor plan with a check-in point and a non-phone option. Have another learner verify the path from the plan alone.', 'Worked response: Rehearse a step-free alternate route, a prearranged check-in method and a shared meeting place. A workable plan accounts for actual access needs and loss of normal communications. Give everyone a way to reach help or reconnect. Source to consult: CDC · Accessible emergency planning.', 'way/human-arc-future/human-arc-method-30/'),
  ('survival-field-drill-19', 'mastery-protection', 619, 'Field drill · Safe Bystander Support & Reporting', 'Complete a scenario decision and demonstrate it on a changed example.', 'You see someone cornered in a community building. A staff desk is visible, and the person causing concern is agitated. Choices: 1. Share names and unverified claims with bystanders. / 2. Get staff or emergency help as appropriate, keep distance, and record observable details. / 3. Move between the two people and issue a threat.', 'Mark the observation, inference, and question that matters to the next action.', 'Write a twenty-second handoff with one direct observation, one uncertainty and a clear request for help.', 'Worked response: Get staff or emergency help as appropriate, keep distance, and record observable details. A safe bystander uses the nearest suitable support and avoids escalation. The factual report records the time, place and conduct while protecting privacy. Source to consult: CISA · De-escalation Action Guide.', 'institution/foundation/architecture/course/'),
  ('survival-field-drill-20', 'mastery-money', 620, 'Field drill · Cash Flow, Reserves & Fraud Checks', 'Complete a scenario decision and demonstrate it on a changed example.', 'Cash on hand is 100. A 150 bill is due Monday and income of 400 arrives Friday. A message also demands immediate wire payment. Choices: 1. Record the Monday shortfall as 50 and verify the payment demand using an independently located contact. / 2. The Friday income means there is no Monday shortfall. / 3. Wire the money before checking the sender to avoid a penalty.', 'Mark the observation, inference, and question that matters to the next action.', 'Create a dated cash calendar and name two options for timing or reserves. Write how you would verify the suspicious demand.', 'Worked response: Record the Monday shortfall as 50 and verify the payment demand using an independently located contact. Timing produces the shortfall. An urgent payment message is checked independently before sending money. Read the normal bill or call a known official number. Source to consult: FTC · How to avoid a scam.', 'institution/foundation/three-apples/'),
  ('survival-field-drill-21', 'mastery-kinship', 621, 'Field drill · Repair After Conflict & Support Networks', 'Complete a scenario decision and demonstrate it on a changed example.', 'A friend shares a private detail after agreeing to keep it private. They offer to repair the harm. Choices: 1. Ask them to identify the action and impact, offer a concrete repair, and respect your decision about further contact. / 2. A generic apology guarantees repair. / 3. Require immediate renewed contact to prove they are sincere.', 'Mark the observation, inference, and question that matters to the next action.', 'Write a short accountable apology and a separate support map that allows the affected person to choose distance.', 'Worked response: Ask them to identify the action and impact, offer a concrete repair, and respect your decision about further contact. Repair should be observable and should leave the other person in control of what contact they want. A person can decline a proposed repair. Source to consult: SAMHSA · Trauma-informed approaches.', 'way/language/read-back-the-exact-words/'),
  ('survival-field-drill-22', 'mastery-homestead', 622, 'Field drill · Fire, Carbon Monoxide & Utility Shutoff Planning', 'Complete a scenario decision and demonstrate it on a changed example.', 'A fictional carbon monoxide alarm sounds. A family member suggests opening windows and staying to find the source. Choices: 1. Stay inside while looking for the defective appliance. / 2. Get everyone to fresh air, contact emergency services from safety and follow responder directions. / 3. Wait indoors to see if the alarm stops.', 'Mark the observation, inference, and question that matters to the next action.', 'Mark where everyone goes and how the alarm response differs from a routine utility-shutoff planning exercise.', 'Worked response: Get everyone to fresh air, contact emergency services from safety and follow responder directions. An alarm calls for prompt action and outside help. The tabletop exercise practices the exit and handoff. Responders determine when return is safe. Source to consult: U.S. Fire Administration · Home fire prevention.', 'way/human-arc-future/human-arc-method-30/'),
  ('survival-field-drill-23', 'mastery-homestead', 623, 'Field drill · Outage Sanitation & Inventory Rotation', 'Complete a scenario decision and demonstrate it on a changed example.', 'A power outage interrupts water service and refrigeration. The household needs to track drinking supply, hygiene supplies, and temperature-sensitive items. Choices: 1. Treat all water and hygiene use as one unlabeled supply. / 2. Track supplies separately, record times and thresholds, and follow official water and food guidance before reuse. / 3. Assume cold storage remained safe if the door was closed.', 'Mark the observation, inference, and question that matters to the next action.', 'Build an outage board with a water status, temperature-sensitive items, an alert source and a resupply trigger.', 'Worked response: Track supplies separately, record times and thresholds, and follow official water and food guidance before reuse. Separate drinking water, other uses and cold-storage decisions. The recorded timeline and local instructions determine resupply and use. Source to consult: CDC · Water safety in an emergency.', 'way/human-arc-future/human-arc-method-30/'),
  ('survival-field-drill-24', 'mastery-learning', 624, 'Field drill · Accessible Practice & Progress Tracking', 'Complete a scenario decision and demonstrate it on a changed example.', 'An exercise must assess whether a learner can classify a record. One format is inaccessible to the learner. Choices: 1. Lower the goal for any learner needing a different format. / 2. Keep the classification goal and offer equivalent accessible formats, then check performance on a new record. / 3. Keep the same format and judge the speed of reading.', 'Mark the observation, inference, and question that matters to the next action.', 'Create a text-based version and a model-based version, agree on one proof criterion, and compare the results after a delay.', 'Worked response: Keep the classification goal and offer equivalent accessible formats, then check performance on a new record. The objective is classification. Access can change while preserving the same evidence of understanding. A transfer test shows whether the decision works on a new record. Source to consult: CAST · Universal Design for Learning.', 'way/human-learning-arc/'),
  ('survival-field-drill-25', 'mastery-civic', 625, 'Field drill · Agendas, Budgets, Public Comment & Appeals', 'Complete a scenario decision and demonstrate it on a changed example.', 'A county agenda lists a proposal. The draft minutes show discussion, and there is no recorded vote. Choices: 1. Announce the proposal is law because it was on the agenda. / 2. Check the official minutes or decision record and identify the rules for participation or review. / 3. Treat a public comment as an appeal filing.', 'Mark the observation, inference, and question that matters to the next action.', 'Write a one-minute public comment using the real agenda item number in the mock packet, then list which document would prove adoption.', 'Worked response: Check the official minutes or decision record and identify the rules for participation or review. Discussion and adoption are different steps. Obtain the actual decision and applicable process before deciding how to participate or seek review. Source to consult: North Carolina General Assembly · Chapter 160D.', 'way/humanities/one-decision/'),
  ('survival-field-drill-26', 'mastery-civic', 626, 'Field drill · Benefits, Public Services & Administrative Review', 'Complete a scenario decision and demonstrate it on a changed example.', 'A fictional agency denial says a document was missing and lists a date, a review procedure and an agency contact. Choices: 1. Assume the reason the agency had in mind and skip the written notice. / 2. Quote the stated reason, confirm the timeline and process with the issuing agency, and set aside the relevant record. / 3. Post the unredacted notice publicly so strangers can interpret it.', 'Mark the observation, inference, and question that matters to the next action.', 'Build a timeline and draft a concise request for clarification. Mark each fact as from the notice, independently checked, or open.', 'Worked response: Quote the stated reason, confirm the timeline and process with the issuing agency, and set aside the relevant record. Work from the written reason and official process. Protect identifiers and confirm the applicable deadline rather than guessing how the agency decided. Source to consult: North Carolina Judicial Branch · Records access.', 'institution/civics/'),
  ('survival-field-drill-27', 'mastery-civic', 627, 'Field drill · Six-Domain Capstone · One Household Scenario', 'Complete a scenario decision and demonstrate it on a changed example.', 'A storm brings a water advisory, a rushed repair offer, a boundary conflict, an unfamiliar procedure and a county alert. The household needs a first response and a replayable record. Choices: 1. Hire the fastest vendor immediately and postpone the other decisions. / 2. Combine every action into one unlabeled message and let the team infer its roles. / 3. Prioritize safety and verified water, check the offer, honor the boundary, rehearse the procedure and record the civic source.', 'Use BUILD, CLEAR, INTEGRATE and VERIFY on the decision log. Start with the verified outcome and work backward to the first missing dependency.', 'Give each role one record. Run the exercise forward and backward and identify the first missing dependency. Verify the final handoff with a second person.', 'Worked response: Prioritize safety and verified water, check the offer, honor the boundary, rehearse the procedure and record the civic source. Use all six domains. Name the safety action, money check, boundary, homestead step, recall test and civic source. Preserve who did what and what would make the team revise it. Source to consult: CDC · Accessible emergency planning.', 'institution/')
